//
// Token Weather, three-chip layout: context bar + cost, 5h limit, weekly limit.
// Based on the token-weather mod from claude-code-playground.
//
// The host reads on(...) and $.noun.method(...) from source, so they are
// spelled literally, and helpers that take $ are top-level functions.

const WINDOWS = {
  five_hour: { label: "5h", ms: 5 * 3600_000 },
  seven_day: { label: "Week", ms: 7 * 24 * 3600_000 },
};

// Last reading: { tokens, window, usd, limits: [{ kind, percentUsed, resetsAt }] }
let reading = null;

export function register(on) {
  on("session.start", async ($, e, next) => {
    const result = await next(e);
    reading = null;
    await takeReading($);
    return result;
  });

  on("turn.complete", async ($, e, next) => {
    const result = await next(e);
    if (e.agentId) {
      return result;
    }
    await takeReading($);
    return result;
  });

  on("ui.render", { component: "AbovePrompt" }, ($, e, next) => {
    if (e.hasSurvey || e.props?.hasSurvey || reading === null) {
      return next(e);
    }
    const { Box, Text } = $.ui.resolve(e);
    return band(Box, Text);
  });
}

async function takeReading($) {
  try {
    const { context, rateLimits, cost } = await $.session.usage();
    if (!context || !context.window) {
      return;
    }
    reading = {
      tokens: context.tokens ?? 0,
      window: context.window,
      usd: cost ? cost.usd : null,
      limits: rateLimits ?? [],
    };
    $.ui.invalidate("ui.render");
  } catch {
    // No reading this turn; the band keeps the last one.
  }
}

// Green when there is room, yellow then red as the share used grows.
function tone(pct) {
  return pct >= 85 ? "red" : pct >= 60 ? "yellow" : "green";
}

function short(n) {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n % 1_000_000 === 0 ? 0 : 1)}M`;
  if (n >= 1_000) return `${Math.round(n / 1_000)}k`;
  return String(n);
}

function duration(ms) {
  const m = Math.max(0, Math.round(ms / 60_000));
  if (m >= 1440) return `${Math.floor(m / 1440)}j`;
  if (m >= 60) return `${Math.floor(m / 60)}h`;
  return `${m}min`;
}

// A thick bar with the label inside: coloured part, then grey part.
function fatBar(Text, pct, width, label, color) {
  const pad = Math.max(0, width - label.length);
  const text = " ".repeat(Math.floor(pad / 2)) + label + " ".repeat(Math.ceil(pad / 2));
  const full = Math.max(0, Math.min(width, Math.round((pct / 100) * width)));
  return [
    Text({ backgroundColor: color, color: "white", bold: true, children: text.slice(0, full) }),
    Text({ backgroundColor: "#3a3a3a", color: "white", bold: true, children: text.slice(full) }),
  ];
}

// A thin line with a dot-sized fill, as in the 5h / Week chips.
function thinBar(Text, pct, width, color) {
  const full = Math.max(1, Math.min(width, Math.round((pct / 100) * width)));
  return [
    Text({ color, children: "━".repeat(full) }),
    Text({ color: "#3a3a3a", children: "━".repeat(width - full) }),
  ];
}

function chip(Box, key, children) {
  return Box({ key, borderStyle: "round", borderDimColor: true, paddingX: 1, gap: 1, children });
}

function band(Box, Text) {
  const chips = [];

  const pct = Math.min(100, (reading.tokens / reading.window) * 100);
  const ctx = [
    Text({ dimColor: true, children: "S" }),
    Box({ children: fatBar(Text, pct, 20, `${short(reading.tokens)}/${short(reading.window)}`, tone(pct)) }),
  ];
  if (reading.usd !== null) {
    ctx.push(Text({ bold: true, children: `$${reading.usd.toFixed(2)}` }));
  }
  chips.push(chip(Box, "ctx", ctx));

  for (const l of reading.limits) {
    const w = WINDOWS[l.kind];
    const used = l.percentUsed;
    const parts = [
      Text({ dimColor: true, children: w ? w.label : l.kind }),
      Box({ children: thinBar(Text, used, 8, tone(used)) }),
      Text({ bold: true, children: `${Math.round(used)}%` }),
    ];
    if (l.resetsAt) {
      const left = Date.parse(l.resetsAt) - Date.now();
      if (w) {
        // Margin: share of the window already elapsed minus share used; positive = ahead.
        const elapsed = Math.min(100, Math.max(0, ((w.ms - left) / w.ms) * 100));
        const d = elapsed - used;
        parts.push(Text({ color: d >= 0 ? "green" : d > -10 ? "yellow" : "red", children: `${d >= 0 ? "+" : ""}${d.toFixed(1)}%` }));
      }
      parts.push(Text({ dimColor: true, children: duration(left) }));
    }
    chips.push(chip(Box, l.kind, parts));
  }

  return Box({ flexDirection: "row", flexWrap: "wrap", children: chips });
}

